// End-to-end: a local relay (wrangler dev, fresh storage) and a stand-in for ChatGPT that publishes a
// client metadata document (CIMD) on localhost. Covers discovery, the authorization page, PKCE, codes,
// tokens, refresh, revocation, the four tools, and that the existing channel API behaves as before.
// Every secret here is generated by the test; nothing touches the deployed relay.

import { test, before, after } from "node:test";
import assert from "node:assert/strict";
import { spawn, spawnSync } from "node:child_process";
import { createServer } from "node:http";
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { randomBytes, createHash } from "node:crypto";

const RELAY_DIR = join(dirname(fileURLToPath(import.meta.url)), "..");
const CLI = join(RELAY_DIR, "..", "plugin", "bin", "ccim");
const PORT = 18000 + Math.floor(Math.random() * 1000);
const BASE = `http://localhost:${PORT}`;
const SECRET = randomBytes(24).toString("base64url");
const ENC_KEY = randomBytes(32).toString("base64");

let relay, relayLog = "", client, CLIENT_PORT, CIMD, CALLBACK, persist;

before(async () => {
  client = createServer((req, res) => {
    if (req.url === "/cimd.json") {
      res.writeHead(200, { "content-type": "application/json" });
      // Shaped like ChatGPT's document as described in OpenAI's docs.
      return res.end(JSON.stringify({ client_id: CIMD, client_name: "Test ChatGPT", redirect_uris: [CALLBACK], token_endpoint_auth_methods_supported: ["none", "private_key_jwt"], token_endpoint_auth_method: "none" }));
    }
    if (req.url === "/wrong-id.json") {
      res.writeHead(200, { "content-type": "application/json" });
      return res.end(JSON.stringify({ client_id: "http://localhost:1/other.json", redirect_uris: [CALLBACK] }));
    }
    res.writeHead(404).end();
  });
  await new Promise((r) => client.listen(0, "127.0.0.1", r));
  CLIENT_PORT = client.address().port;
  CIMD = `http://localhost:${CLIENT_PORT}/cimd.json`;
  CALLBACK = `http://localhost:${CLIENT_PORT}/callback`;

  persist = mkdtempSync(join(tmpdir(), "ccim-flow-"));
  const vars = { OAUTH_ISSUER: BASE, MCP_ALLOWED_BINDINGS: "xd-bridge/xd-dot", OAUTH_REDIRECT_HOSTS: "localhost", OAUTH_ENC_KEY: ENC_KEY };
  relay = spawn(join(RELAY_DIR, "node_modules", ".bin", "wrangler"), ["dev", "--local", "--port", String(PORT), "--persist-to", persist, "--show-interactive-dev-session=false", ...Object.entries(vars).flatMap(([k, v]) => ["--var", `${k}:${v}`])], { cwd: RELAY_DIR, stdio: ["ignore", "pipe", "pipe"] });
  relay.stdout.on("data", (d) => (relayLog += d));
  relay.stderr.on("data", (d) => (relayLog += d));
  for (let i = 0; i < 120; i++) {
    if (/Ready on/.test(relayLog)) break;
    await new Promise((r) => setTimeout(r, 500));
  }
  assert.match(relayLog, /Ready on/, "wrangler dev did not start");
});

after(async () => {
  relay?.kill();
  client?.close();
  if (persist) rmSync(persist, { recursive: true, force: true });
});

// ---- helpers -------------------------------------------------------------------------------------

const responses = [];
async function http(method, path, { body, form, token, secret, headers = {} } = {}) {
  const res = await fetch(BASE + path, {
    method,
    redirect: "manual",
    headers: {
      ...(body && { "content-type": "application/json" }),
      ...(form && { "content-type": "application/x-www-form-urlencoded" }),
      ...(token && { authorization: `Bearer ${token}` }),
      ...(secret && { "x-ccim-secret": secret }),
      ...headers,
    },
    body: body ? JSON.stringify(body) : form ? new URLSearchParams(form).toString() : undefined,
  });
  const text = await res.text();
  responses.push(text + JSON.stringify([...res.headers]));
  let data = null;
  try { data = JSON.parse(text); } catch {}
  return { status: res.status, headers: res.headers, text, data };
}

const channel = (method, op, opts) => http(method, `/c/xd-bridge/${op}`, opts);

let rpcId = 0;
async function mcp(method, params, token) {
  const res = await http("POST", "/mcp", { body: { jsonrpc: "2.0", id: ++rpcId, method, params }, token });
  return res.status === 200 ? res.data.result ?? res.data : res;
}
const tool = (name, args, token) => mcp("tools/call", { name, arguments: args }, token);

const pkce = () => {
  const verifier = randomBytes(32).toString("base64url");
  return { verifier, challenge: createHash("sha256").update(verifier).digest("base64url") };
};

function authorizeUrl(overrides = {}) {
  const p = new URLSearchParams({ response_type: "code", client_id: CIMD, redirect_uri: CALLBACK, state: "st-" + randomBytes(6).toString("hex"), code_challenge_method: "S256", resource: BASE, scope: "ccim:read ccim:write", ...overrides });
  for (const [k, v] of Object.entries(overrides)) if (v === null) p.delete(k);
  return `/oauth/authorize?${p}`;
}

// Opens the authorization page and submits it, the way XD would in the browser.
async function authorize({ member = "xd-dot", secret = SECRET, clientId = CIMD, scope } = {}) {
  const { verifier, challenge } = pkce();
  const state = "st-" + randomBytes(6).toString("hex");
  const page = await http("GET", authorizeUrl({ client_id: clientId, code_challenge: challenge, state, ...(scope && { scope }) }));
  assert.equal(page.status, 200, page.text);
  const request = page.text.match(/name="request" value="([0-9a-f]{32})"/)[1];
  const posted = await http("POST", "/oauth/authorize", { form: { request, channel: "xd-bridge", member, secret, action: "allow" } });
  if (posted.status !== 302) return { page: posted, request };
  const loc = new URL(posted.headers.get("location"));
  return { loc, state, verifier, clientId, code: loc.searchParams.get("code") };
}

const exchange = (a, extra = {}) =>
  http("POST", "/oauth/token", { form: { grant_type: "authorization_code", code: a.code, redirect_uri: CALLBACK, client_id: a.clientId, code_verifier: a.verifier, resource: BASE, ...extra } });

async function connect(opts) {
  const a = await authorize(opts);
  assert.ok(a.code, a.page?.text);
  const t = await exchange(a);
  assert.equal(t.status, 200, t.text);
  return t.data;
}

// ---- the flow ------------------------------------------------------------------------------------

let alice; // a CLI-style member that exists before Dot connects

test("setup: a channel with one CLI member", async () => {
  const j = await channel("POST", "join", { body: { handle: "alice" }, secret: SECRET });
  assert.equal(j.status, 200);
  alice = j.data.token;
});

test("discovery metadata", async () => {
  const pr = await http("GET", "/.well-known/oauth-protected-resource");
  assert.equal(pr.data.resource, BASE);
  assert.deepEqual(pr.data.authorization_servers, [BASE]);
  assert.deepEqual(pr.data.scopes_supported, ["ccim:read", "ccim:write"]);
  assert.equal((await http("GET", "/.well-known/oauth-protected-resource/mcp")).data.resource, `${BASE}/mcp`);

  const as = (await http("GET", "/.well-known/oauth-authorization-server")).data;
  assert.equal(as.issuer, BASE);
  assert.deepEqual(as.code_challenge_methods_supported, ["S256"]);
  assert.equal(as.client_id_metadata_document_supported, true);
  assert.equal(as.authorization_response_iss_parameter_supported, true);
  assert.deepEqual(as.token_endpoint_auth_methods_supported, ["none"]);
  assert.equal(as.registration_endpoint, `${BASE}/oauth/register`);
});

test("tools need a token; a bad token gets 401 with WWW-Authenticate", async () => {
  const list = await mcp("tools/list");
  assert.deepEqual(list.tools.map((t) => t.name), ["ccim_probe", "ccim_who", "ccim_inbox", "ccim_ack", "ccim_send"]);
  for (const t of list.tools.slice(1)) assert.equal(t.securitySchemes[0].type, "oauth2");
  assert.ok(!list.tools.some((t) => "scope" in t));

  const r = await tool("ccim_who", {});
  assert.equal(r.isError, true);
  assert.match(r._meta["mcp/www_authenticate"][0], /^Bearer resource_metadata="[^"]+\/\.well-known\/oauth-protected-resource", error="invalid_token", error_description="/);

  const bad = await mcp("tools/list", {}, "cca_not-a-real-token");
  assert.equal(bad.status, 401);
  assert.match(bad.headers.get("www-authenticate"), /error="invalid_token", error_description="/);
  assert.equal((await tool("ccim_probe", {})).structuredContent.ok, true);
});

test("authorization request validation", async () => {
  const { challenge } = pkce();
  // Unknown client or redirect mismatch: shown as a page, never redirected.
  assert.equal((await http("GET", authorizeUrl({ code_challenge: challenge, client_id: "http://localhost:1/nope.json" }))).status, 400);
  assert.equal((await http("GET", authorizeUrl({ code_challenge: challenge, client_id: `http://localhost:${CLIENT_PORT}/wrong-id.json` }))).status, 400);
  assert.equal((await http("GET", authorizeUrl({ code_challenge: challenge, redirect_uri: CALLBACK + "/x" }))).status, 400);
  assert.equal((await http("GET", authorizeUrl({ code_challenge: challenge, redirect_uri: CALLBACK.replace("localhost", "127.0.0.1") }))).status, 400);

  // Known client and redirect: errors go back to the client with state and iss.
  const back = async (overrides) => {
    const r = await http("GET", authorizeUrl({ code_challenge: challenge, state: "keep-me", ...overrides }));
    assert.equal(r.status, 302);
    const loc = new URL(r.headers.get("location"));
    assert.equal(loc.origin + loc.pathname, CALLBACK);
    assert.equal(loc.searchParams.get("state"), "keep-me");
    assert.equal(loc.searchParams.get("iss"), BASE);
    return loc.searchParams.get("error");
  };
  assert.equal(await back({ code_challenge: null }), "invalid_request");
  assert.equal(await back({ code_challenge_method: "plain" }), "invalid_request");
  assert.equal(await back({ code_challenge_method: null }), "invalid_request");
  assert.equal(await back({ response_type: "token" }), "unsupported_response_type");
  assert.equal(await back({ resource: "https://elsewhere.example" }), "invalid_target");
  assert.equal(await back({ resource: `${BASE}/other` }), "invalid_target");
});

test("authorization page: wrong secret, binding not allowed, never takes over a CLI member", async () => {
  const wrong = await authorize({ secret: "x".repeat(24) });
  assert.match(wrong.page.text, /Wrong channel secret/);
  assert.ok(!wrong.page.text.includes("x".repeat(24)), "secret echoed back");

  const other = await authorize({ member: "alice" });
  assert.match(other.page.text, /not enabled/);

  // Someone joins as xd-dot with the CLI first: authorization must refuse, and their token must keep working.
  const cli = await channel("POST", "join", { body: { handle: "xd-dot" }, secret: SECRET });
  const taken = await authorize();
  assert.match(taken.page.text, /already used by another session/);
  assert.equal((await channel("GET", "who", { token: cli.data.token })).data.you, "xd-dot");
  await channel("POST", "leave", { body: {}, token: cli.data.token });
});

test("too many failed attempts end the request", async () => {
  const { challenge } = pkce();
  const page = await http("GET", authorizeUrl({ code_challenge: challenge, state: "s1" }));
  const request = page.text.match(/name="request" value="([0-9a-f]{32})"/)[1];
  let last;
  for (let i = 0; i < 5; i++) last = await http("POST", "/oauth/authorize", { form: { request, channel: "xd-bridge", member: "xd-dot", secret: "y".repeat(20), action: "allow" } });
  assert.equal(last.status, 302);
  assert.equal(new URL(last.headers.get("location")).searchParams.get("error"), "access_denied");
  const again = await http("POST", "/oauth/authorize", { form: { request, channel: "xd-bridge", member: "xd-dot", secret: SECRET, action: "allow" } });
  assert.equal(again.status, 400);
});

test("deny returns access_denied", async () => {
  const { challenge } = pkce();
  const page = await http("GET", authorizeUrl({ code_challenge: challenge, state: "deny-state" }));
  const request = page.text.match(/name="request" value="([0-9a-f]{32})"/)[1];
  const r = await http("POST", "/oauth/authorize", { form: { request, action: "deny" } });
  const loc = new URL(r.headers.get("location"));
  assert.equal(loc.searchParams.get("error"), "access_denied");
  assert.equal(loc.searchParams.get("state"), "deny-state");
});

let tokens;

test("code exchange: PKCE, single use, redirect and client must match", async () => {
  const a = await authorize();
  assert.equal(a.loc.searchParams.get("state"), a.state);
  assert.equal(a.loc.searchParams.get("iss"), BASE);
  assert.match(a.code, /^cc_/);

  // Wrong verifier burns the code.
  assert.equal((await exchange(a, { code_verifier: pkce().verifier })).data.error, "invalid_grant");
  assert.equal((await exchange(a)).data.error, "invalid_grant");

  const b = await authorize();
  assert.equal((await exchange(b, { redirect_uri: CALLBACK + "?x=1" })).data.error, "invalid_grant");
  const c = await authorize();
  assert.equal((await exchange(c, { client_id: "someone-else" })).data.error, "invalid_grant");
  const d = await authorize();
  assert.equal((await exchange(d, { resource: "https://elsewhere.example" })).data.error, "invalid_target");

  const e = await authorize();
  const t = await exchange(e);
  assert.equal(t.status, 200);
  assert.equal(t.headers.get("cache-control"), "no-store");
  assert.equal(t.data.token_type, "Bearer");
  assert.equal(t.data.expires_in, 3600);
  assert.equal(t.data.scope, "ccim:read ccim:write");
  assert.match(t.data.access_token, /^cca_/);
  assert.match(t.data.refresh_token, /^ccr_/);
  assert.equal((await tool("ccim_who", {}, t.data.access_token)).structuredContent.you, "xd-dot");

  // Reusing a code revokes what it produced.
  assert.equal((await exchange(e)).data.error, "invalid_grant");
  assert.equal((await mcp("tools/list", {}, t.data.access_token)).status, 401);

  tokens = await connect();
});

test("ccim_who reports the bound member and ignores identity arguments", async () => {
  const who = await tool("ccim_who", {}, tokens.access_token);
  assert.equal(who.structuredContent.you, "xd-dot");
  assert.equal(who.structuredContent.channel, "xd-bridge");
  assert.deepEqual(who.structuredContent.members.map((m) => m.handle).sort(), ["alice", "xd-dot"]);

  for (const args of [{ member: "alice" }, { from: "alice" }, { channel: "other" }]) {
    const r = await tool("ccim_who", args, tokens.access_token);
    assert.equal(r.isError, true);
    assert.match(r.content[0].text, /unexpected argument/);
  }
  const spoof = await tool("ccim_send", { to: "alice", text: "hi", client_msg_id: "spoof-0001", from: "alice" }, tokens.access_token);
  assert.equal(spoof.isError, true);
});

let sentByMcp = 0;

test("ccim_send: delivered, retries with the same client_msg_id are not sent twice", async () => {
  const first = await tool("ccim_send", { to: "alice", text: "hello from dot", client_msg_id: "msg-0001" }, tokens.access_token);
  assert.equal(first.isError, undefined, first.content[0].text);
  assert.equal(first.structuredContent.duplicate, false);
  sentByMcp++;
  const retry = await tool("ccim_send", { to: "alice", text: "hello from dot", client_msg_id: "msg-0001" }, tokens.access_token);
  assert.equal(retry.structuredContent.duplicate, true);
  assert.equal(retry.structuredContent.id, first.structuredContent.id);

  const inbox = (await channel("GET", "inbox", { token: alice })).data.messages;
  assert.equal(inbox.length, 1);
  assert.equal(inbox[0].from, "xd-dot");
  assert.equal(inbox[0].text, "hello from dot");
  await channel("POST", "ack", { body: { ids: [inbox[0].id] }, token: alice });

  const reused = await tool("ccim_send", { to: "alice", text: "something else", client_msg_id: "msg-0001" }, tokens.access_token);
  assert.equal(reused.isError, true);
  assert.match(reused.content[0].text, /already used for a different message/);

  assert.equal((await tool("ccim_send", { to: "xd-dot", text: "me", client_msg_id: "self-0001" }, tokens.access_token)).isError, true);
  const unknown = await tool("ccim_send", { to: "bob", text: "x", client_msg_id: "bob-00001" }, tokens.access_token);
  assert.match(unknown.content[0].text, /No "bob"/);
  assert.equal((await tool("ccim_send", { to: "alice", text: "x" }, tokens.access_token)).isError, true);
});

test("ccim_inbox reads without acking; ccim_ack removes", async () => {
  const ids = [];
  for (const text of ["one", "two", "three"]) ids.push((await channel("POST", "send", { body: { to: "xd-dot", text }, token: alice })).data.id);

  const a = await tool("ccim_inbox", {}, tokens.access_token);
  assert.deepEqual(a.structuredContent.messages.map((m) => m.text), ["one", "two", "three"]);
  assert.equal(a.structuredContent.messages[0].from, "alice");
  const b = await tool("ccim_inbox", {}, tokens.access_token);
  assert.deepEqual(b.structuredContent.messages.map((m) => m.id), ids, "reading must not ack");

  const page = await tool("ccim_inbox", { limit: 2 }, tokens.access_token);
  assert.equal(page.structuredContent.messages.length, 2);
  assert.equal(page.structuredContent.more, true);
  const rest = await tool("ccim_inbox", { after_id: page.structuredContent.next_after_id }, tokens.access_token);
  assert.deepEqual(rest.structuredContent.messages.map((m) => m.text), ["three"]);

  assert.equal((await tool("ccim_ack", { ids: ids.slice(0, 2) }, tokens.access_token)).isError, undefined);
  assert.deepEqual((await tool("ccim_inbox", {}, tokens.access_token)).structuredContent.messages.map((m) => m.text), ["three"]);
  assert.equal((await tool("ccim_ack", { ids: ids.slice(0, 2) }, tokens.access_token)).isError, undefined, "acking twice is harmless");
  await tool("ccim_ack", { ids: [ids[2]] }, tokens.access_token);
  assert.equal((await tool("ccim_inbox", {}, tokens.access_token)).content[0].text, "No unacknowledged messages.");
  assert.equal((await tool("ccim_ack", { ids: [] }, tokens.access_token)).isError, true);
});

test("the 24-message loop guard still applies, and duplicates do not count", async () => {
  // So far: 1 send by MCP, 3 by alice, since the channel was created with no human reset.
  let total = sentByMcp + 3;
  let blocked;
  for (let i = 0; i < 30 && !blocked; i++) {
    const r = await tool("ccim_send", { to: "alice", text: `loop ${i}`, client_msg_id: `loop-${String(i).padStart(4, "0")}` }, tokens.access_token);
    if (r.isError) blocked = r;
    else {
      total++;
      await tool("ccim_send", { to: "alice", text: `loop ${i}`, client_msg_id: `loop-${String(i).padStart(4, "0")}` }, tokens.access_token);
    }
  }
  assert.equal(total, 24);
  assert.match(blocked.content[0].text, /no human typing/);
  // The CLI's "human typed" reset still works, and MCP has no tool for it.
  assert.equal((await channel("POST", "human", { body: {}, token: alice })).status, 200);
  assert.equal((await tool("ccim_send", { to: "alice", text: "after reset", client_msg_id: "reset-0001" }, tokens.access_token)).isError, undefined);
  const inbox = (await channel("GET", "inbox", { token: alice })).data.messages;
  await channel("POST", "ack", { body: { ids: inbox.map((m) => m.id) }, token: alice });
});

test("scope: a read-only token cannot send", async () => {
  const ro = await connect({ scope: "ccim:read" });
  assert.equal(ro.scope, "ccim:read");
  assert.equal((await tool("ccim_who", {}, ro.access_token)).isError, undefined);
  const r = await tool("ccim_send", { to: "alice", text: "x", client_msg_id: "scope-0001" }, ro.access_token);
  assert.equal(r.isError, true);
  assert.match(r._meta["mcp/www_authenticate"][0], /error="insufficient_scope"/);
  // Authorizing again replaced the previous grant.
  assert.equal((await mcp("tools/list", {}, tokens.access_token)).status, 401);
  tokens = await connect();
});

test("refresh rotates; reusing an old refresh token ends the grant", async () => {
  const r1 = await http("POST", "/oauth/token", { form: { grant_type: "refresh_token", refresh_token: tokens.refresh_token, client_id: CIMD, resource: BASE } });
  assert.equal(r1.status, 200);
  assert.notEqual(r1.data.refresh_token, tokens.refresh_token);
  assert.equal((await tool("ccim_who", {}, r1.data.access_token)).structuredContent.you, "xd-dot");

  const wrongClient = await http("POST", "/oauth/token", { form: { grant_type: "refresh_token", refresh_token: r1.data.refresh_token, client_id: "other" } });
  assert.equal(wrongClient.data.error, "invalid_grant");
  const widen = await http("POST", "/oauth/token", { form: { grant_type: "refresh_token", refresh_token: r1.data.refresh_token, client_id: CIMD, scope: "ccim:read ccim:admin" } });
  assert.equal(widen.data.error, "invalid_scope");

  const replay = await http("POST", "/oauth/token", { form: { grant_type: "refresh_token", refresh_token: tokens.refresh_token, client_id: CIMD } });
  assert.equal(replay.data.error, "invalid_grant");
  assert.equal((await mcp("tools/list", {}, r1.data.access_token)).status, 401);
  assert.equal((await http("POST", "/oauth/token", { form: { grant_type: "refresh_token", refresh_token: r1.data.refresh_token, client_id: CIMD } })).data.error, "invalid_grant");
});

test("reconnecting reuses the member: no rejoin, queued messages kept", async () => {
  await channel("POST", "send", { body: { to: "xd-dot", text: "while away" }, token: alice });
  tokens = await connect();
  const inbox = await tool("ccim_inbox", {}, tokens.access_token);
  assert.deepEqual(inbox.structuredContent.messages.map((m) => m.text), ["while away"]);
  await tool("ccim_ack", { ids: inbox.structuredContent.messages.map((m) => m.id) }, tokens.access_token);
  assert.match(relayLog, /"event":"oauth_granted"[^\n]*"reused":true/);
});

test("revocation endpoint ends the grant", async () => {
  const other = await http("POST", "/oauth/revoke", { form: { token: tokens.access_token, client_id: "someone-else" } });
  assert.equal(other.status, 200);
  assert.equal((await tool("ccim_who", {}, tokens.access_token)).structuredContent?.you, "xd-dot", "another client cannot revoke");

  assert.equal((await http("POST", "/oauth/revoke", { form: { token: tokens.refresh_token, client_id: CIMD } })).status, 200);
  assert.equal((await mcp("tools/list", {}, tokens.access_token)).status, 401);
  assert.equal((await http("POST", "/oauth/revoke", { form: { token: "nonsense", client_id: CIMD } })).status, 200);
});

test("member taken over by a CLI join: the grant stops working, the CLI member is untouched", async () => {
  tokens = await connect();
  const cli = await channel("POST", "join", { body: { handle: "xd-dot" }, secret: SECRET });
  const r = await tool("ccim_who", {}, tokens.access_token);
  assert.equal(r.isError, true);
  assert.match(r._meta["mcp/www_authenticate"][0], /invalid_token/);
  assert.equal((await mcp("tools/list", {}, tokens.access_token)).status, 401);
  assert.equal((await channel("GET", "who", { token: cli.data.token })).data.you, "xd-dot");
  await channel("POST", "leave", { body: {}, token: cli.data.token });
});

test("manage page: wrong secret refused; revoke and leave removes the member", async () => {
  tokens = await connect();
  assert.match((await http("POST", "/oauth/manage", { form: { channel: "xd-bridge", secret: "z".repeat(20) } })).text, /Wrong channel or secret/);
  const list = await http("POST", "/oauth/manage", { form: { channel: "xd-bridge", secret: SECRET } });
  assert.match(list.text, /<b>xd-dot<\/b>: connected/);

  const revoked = await http("POST", "/oauth/manage", { form: { channel: "xd-bridge", secret: SECRET, member: "xd-dot", action: "revoke" } });
  assert.match(revoked.text, /no active connection/);
  assert.equal((await mcp("tools/list", {}, tokens.access_token)).status, 401);
  assert.ok((await channel("GET", "who", { token: alice })).data.members.some((m) => m.handle === "xd-dot"), "plain revoke keeps the member");

  await http("POST", "/oauth/manage", { form: { channel: "xd-bridge", secret: SECRET, member: "xd-dot", action: "revoke_leave" } });
  assert.ok(!(await channel("GET", "who", { token: alice })).data.members.some((m) => m.handle === "xd-dot"));
});

test("dynamic client registration as the fallback", async () => {
  const evil = await http("POST", "/oauth/register", { body: { redirect_uris: ["https://evil.example/cb"] } });
  assert.equal(evil.data.error, "invalid_redirect_uri");
  const secretClient = await http("POST", "/oauth/register", { body: { redirect_uris: [CALLBACK], token_endpoint_auth_method: "client_secret_basic" } });
  assert.equal(secretClient.status, 400);
  const reg = await http("POST", "/oauth/register", { body: { client_name: "DCR client", redirect_uris: [CALLBACK] } });
  assert.equal(reg.status, 201);
  const t = await connect({ clientId: reg.data.client_id });
  assert.equal((await tool("ccim_who", {}, t.access_token)).structuredContent.you, "xd-dot");
});

test("authorization page headers", async () => {
  const { challenge } = pkce();
  const page = await http("GET", authorizeUrl({ code_challenge: challenge }));
  assert.equal(page.headers.get("cache-control"), "no-store");
  assert.equal(page.headers.get("x-frame-options"), "DENY");
  assert.match(page.headers.get("content-security-policy"), /frame-ancestors 'none'/);
  assert.match(page.text, /type="password"/);
});

test("existing channel API unchanged: newest join still takes over, CLI works end to end", async () => {
  const one = await channel("POST", "join", { body: { handle: "carol" }, secret: SECRET });
  const two = await channel("POST", "join", { body: { handle: "carol" }, secret: SECRET });
  assert.equal((await channel("GET", "who", { token: one.data.token })).status, 401);
  assert.equal((await channel("GET", "who", { token: two.data.token })).status, 200);
  assert.equal((await channel("POST", "join", { body: { handle: "carol" }, secret: "w".repeat(20) })).status, 403);
  // Joining a new channel still creates it.
  assert.equal((await http("POST", "/c/fresh-channel/join", { body: { handle: "dan" }, secret: randomBytes(18).toString("base64url") })).data.created, true);

  const home = mkdtempSync(join(tmpdir(), "ccim-cli-"));
  try {
    const env = { ...process.env, CCIM_HOME: home, CCIM_SESSION: "flow-test", CCIM_HOST: "claude", CCIM_RELAY: BASE };
    const run = (...args) => spawnSync(process.execPath, [CLI, ...args], { env, encoding: "utf8" });
    assert.equal(run("join", "xd-bridge/erin", "--secret", SECRET).status, 0);
    const sent = run("send", "alice", "from the cli");
    assert.equal(sent.status, 0, sent.stderr);
    assert.match(sent.stdout, /-> alice: offline, queued/);
    assert.match(run("who").stdout, /erin/);
  } finally {
    rmSync(home, { recursive: true, force: true });
  }
});

test("no secret or OAuth token appears in the relay log, and the secret never in a response", async () => {
  assert.ok(!relayLog.includes(SECRET), "channel secret in log");
  assert.ok(!relayLog.includes(ENC_KEY), "encryption key in log");
  assert.ok(!/cca_|ccr_|cc_[A-Za-z0-9_-]{20}/.test(relayLog), "OAuth token or code in log");
  assert.ok(!responses.some((r) => r.includes(SECRET)), "channel secret in a response");
  assert.ok(!responses.some((r) => r.includes(ENC_KEY)), "encryption key in a response");
});
